Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Import ListNotations.
Open Scope Z_scope.

Definition HUF_TABLELOG_MAX : Z := 12.

(* [comment removed for export] *)
(* [comment removed for export] *)

(* [comment removed for export] *)
Record deltX1 := mkX1 { x1_nbBits : Z; x1_byte : Z }.
Definition x1_default : deltX1 := mkX1 0 0.

Definition x1_cell (dt : list deltX1) (i : Z) : res deltX1 :=
  if (0 <=? i) && (i <? Zlength dt) then Ok (nth (Z.to_nat i) dt x1_default) else Ub.

Definition x1_cell_ok (dtLog : Z) (c : deltX1) : Prop :=
  0 <= x1_nbBits c <= dtLog /\ 0 <= x1_byte c < 256.

Definition x1_table_ok (dt : list deltX1) (dtLog : Z) : Prop :=
  1 <= dtLog <= HUF_TABLELOG_MAX /\ 2^dtLog <= Zlength dt /\
  forall i, 0 <= i < 2^dtLog -> x1_cell_ok dtLog (nth (Z.to_nat i) dt x1_default).

