(* [comment removed for export] *)

(* [comment removed for export] *)
Record xstate := mkXS { xs_out : list Z; xs_bd : bitD }.

Section DecodeX1.
  Variables (src : list Z) (dt : list deltX1) (dtLog : Z).

  (* [comment removed for export] *)
  Definition decode_symbol_x1 (d : bitD) : res (Z * bitD) :=
    let v := look_bits_fast d dtLog in
    let! c := x1_cell dt v in
    Ok (x1_byte c, skip_bits d (x1_nbBits c)).

  (* [comment removed for export] *)
  Definition dec1 (x : xstate) : res xstate :=
    let! r := decode_symbol_x1 (xs_bd x) in
    let '(b, d') := r in Ok (mkXS (xs_out x ++ [b]) d').

  (* [comment removed for export] *)
  Definition dec4 (x : xstate) : res xstate :=
    let! x := dec1 x in let! x := dec1 x in let! x := dec1 x in dec1 x.

  (* [comment removed for export] *)
  Fixpoint loop4 (fuel : nat) (n : Z) (x : xstate) : res xstate :=
    match fuel with
    | O => NoFuel
    | S f =>
        let! r := reload_dstream src (xs_bd x) in
        let '(st, d) := r in
        let x := mkXS (xs_out x) d in
        if dstatus_eqb st Unfinished && (Zlength (xs_out x) <? n - 3)
        then let! x' := dec4 x in loop4 f n x'
        else Ok x
    end.

  (* [comment removed for export] *)
  Fixpoint loop1 (fuel : nat) (n : Z) (x : xstate) : res xstate :=
    match fuel with
    | O => NoFuel
    | S f => if Zlength (xs_out x) <? n then let! x' := dec1 x in loop1 f n x' else Ok x
    end.

  (* [comment removed for export] *)
  Definition decode_stream_x1 (n : Z) (d : bitD) : res xstate :=
    let x0 := mkXS [] d in
    let! x := (if 3 <? n then loop4 (S (Z.to_nat n)) n x0
               else let! r := reload_dstream src d in let '(_, d') := r in Ok (mkXS [] d')) in
    loop1 (S (Z.to_nat n)) n x.

  (* [comment removed for export] *)
  Definition decompress1X1 (dstSize : Z) : res (list Z) :=
    let! d := init_dstream src in
    let! x := decode_stream_x1 dstSize d in
    if end_of_dstream (xs_bd x) then Ok (xs_out x) else Err ZSTD_error_corruption_detected.
End DecodeX1.

