Section SafetyX1.
  Variables (src : list Z) (dt : list deltX1) (dtLog : Z).
  Hypothesis HB : all_bytes src.
  Hypothesis HT : x1_table_ok dt dtLog.
  Let len : Z := Zlength src.

  Definition xs_ok (x : xstate) : Prop :=
    bitD_ok len (xs_bd x) /\ Forall (fun b => 0 <= b < 256) (xs_out x).

  Lemma decode_symbol_x1_ok d : bitD_ok len d ->
    exists b d', decode_symbol_x1 dt dtLog d = Ok (b, d') /\ 0 <= b < 256 /\ bitD_ok len d' /\
      bd_ptr d' = bd_ptr d /\ bd_zero d' = bd_zero d /\ bd_cont d' = bd_cont d /\
      (exists nb, 0 <= nb <= dtLog /\ bd_bits d' = u32 (bd_bits d + nb)).
Proof.
