  Lemma dec4_ok x : xs_ok x ->
    exists x', dec4 dt dtLog x = Ok x' /\ xs_ok x' /\ Zlength (xs_out x') = Zlength (xs_out x) + 4 /\
      bd_ptr (xs_bd x') = bd_ptr (xs_bd x) /\ bd_zero (xs_bd x') = bd_zero (xs_bd x) /\
      (0 <= bd_bits (xs_bd x) -> bd_bits (xs_bd x) + 4 * dtLog < 2^32 ->
